<?php
namespace App\Http\Controllers;
use App\Models\User;use App\Models\Role;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class UserController extends Controller {public function index(){return view('users.index',['users'=>User::with('roles')->latest()->paginate(15)]);}public function create(){return view('users.create');}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255','phone'=>'nullable|string|max:50','email'=>'nullable|email|max:255|unique:users,email','password'=>'required|string|min:8']);$d['is_verified']=$r->boolean('is_verified');$u=User::create($d);$u->roles()->sync([Role::where('name','common_trader')->firstOrFail()->id]);return redirect()->route('users.index')->with('success','User created.');}public function edit(User $user){return view('users.edit',compact('user'));}public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|string|max:255','phone'=>'nullable|string|max:50','email'=>'nullable|email|max:255|unique:users,email,'.$user->id,'password'=>'nullable|string|min:8']);if(empty($d['password']))unset($d['password']);$d['is_verified']=$r->boolean('is_verified');$user->update($d);return back()->with('success','User updated.');}public function destroy(User $user){$user->delete();return back()->with('success','User deleted.');}}
